// OWNER (2026-09-25): at most four lanes running at a time. A promise semaphore gates every agent() call;
// parallel()/pipeline() still fan out, but only MAX_LANES agents are live at once (the rest queue in FIFO order).
const MAX_LANES = (typeof args === 'object' && args && args.maxLanes) || 4   // owner cap: 4; lower it at launch when other lanes are live
let liveLanes = 0
const laneQueue = []
const acquireLane = () => new Promise((resolve) => { if (liveLanes < MAX_LANES) { liveLanes++; resolve() } else laneQueue.push(resolve) })
const releaseLane = () => { const next = laneQueue.shift(); if (next) next(); else liveLanes-- }
const limited = async (fn) => { await acquireLane(); try { return await fn() } finally { releaseLane() } }
