const isStandIn = (phaseName) => !!STANDIN_MODEL && (!STANDIN_PHASES || STANDIN_PHASES.includes(phaseName))
const standInNote = (label) => `

STAND-IN NOTICE (owner, 2026-09-25: "run the rest on Opus 5.5, but mark everything that has not gone through the touch of Fable for review next time we have Fable"). You are running on ${STANDIN_MODEL} as a STAND-IN for the Fable seat ${label}. Do the full job to the standard the Fable seat would. MARKING RULES: (1) directly under the title of every output file you write, put the line: > PENDING FABLE REVIEW — written by ${STANDIN_MODEL} standing in for the Fable seat ${label} (2026-09-25); queued in docs/FABLE-REVIEW-QUEUE.md. (2) If you change a file that a Fable seat wrote (for example docs/ARCHITECTURE.md), put the line > PENDING FABLE REVIEW — revised by ${STANDIN_MODEL} stand-in (${label}) directly under the heading of every section you changed. (3) When your work is complete, APPEND (never rewrite the file) one row to the table at the end of docs/FABLE-REVIEW-QUEUE.md: | A-${label} | A | what you produced | your output file(s) and changed sections | ${STANDIN_MODEL} stand-in | today's date | PENDING | the 1–3 judgments a Fable reviewer should re-check first |. If you resumed from disk under the RESUME RULE and produced or changed nothing, add no banner and no row.`
const fable = (prompt, label, phaseName, schema) => { const s = isStandIn(phaseName); return limited(() => agent(s ? prompt + standInNote(label) : prompt, { label, phase: phaseName, schema, agentType: 'general-purpose', model: s ? STANDIN_MODEL : 'fable' })) }
const opus = (prompt, label, phaseName, schema) => limited(() => agent(prompt, { label, phase: phaseName, schema, agentType: 'general-purpose', model: OPUS_MODEL }))

// ───────────────────────── Assess → Challenge (pipeline per reference) + Mine (parallel) ─────────────────────────
const assessPrompt = (r) => `${GROUND}

LANE confidence/${r.id}. You are the confidence assessor for ${r.name}. Read, in this order and under the READING BUDGET rule (≈${r.kb} KB in total): ${ordered(r.files).map(F).join(', ')}. Consult ${r.captures} reports where a number is needed.
Build a capability matrix: one row per distinct capability of the reference (generation stages, geometry primitives, features/options, rendering conventions, labels, export, editing, and for FTG the people/economy/time simulation and data scale). For each row give: evidence summary with tags + citations; what is known; what a re-implementer must still invent; and FOUR separate confidences in [0,1], each with a one-line justification:
 - conf_functional: an expert team could build behaviour-equivalent functionality (same feature, same option surface, statistically similar structure);
 - conf_visual: output a viewer would place in the same quality/style class;
 - conf_algorithm_identity: our derivation would actually match THEIR algorithm (not just its output) — this is what "deriving their code" means;
 - conf_seed_exact: same seed → same map (requires their exact RNG draw order and constants — be honest, this is ≈0 without source except where the open-source ancestor still applies).
Also: effort estimate (person-weeks, expert), the 10 riskiest unknowns ranked, and which cheap experiment (more captures, parameter sweeps, measurements on screenshots/payloads) would raise confidence most.
Write docs/confidence/${r.id}.md.`

const challengePrompt = (r, lens, a) => `${GROUND}

LANE confidence/${r.id}-challenge-${lens.key}. You are an adversarial reviewer of the confidence assessment docs/confidence/${r.id}.md for ${r.name} (overall claimed: ${a ? JSON.stringify(a.overall) : 'see file'}).
LENS — ${lens.brief}
Method: read the assessment fully, then go to the evidence (findings files ${r.files.map(F).join(', ')} and, for at least 10 rows, the ORIGINAL posts/devlogs/docs/captures they cite) and try to REFUTE the numbers. Default to refuting when the cited evidence does not actually support the rating. Every adjustment must quote or pinpoint what you checked.
Write docs/confidence/${r.id}-challenge-${lens.key}.md (table of adjustments with from→to, reason, evidence checked; plus rows you tried to refute and could not).`

const LENSES = [
  { key: 'over', brief: 'OVER-CONFIDENCE HUNTER. Find rows rated higher than the evidence allows: [INFERRED] treated as [STATED]; a named feature mistaken for a described method; visual parity assumed from one screenshot; hidden constants/heuristics; robustness work the creator says took years; combinatorial interaction between features; content/data authoring cost (names, tables, presets).' },
  { key: 'under', brief: 'UNDER-CONFIDENCE HUNTER. Find rows rated lower than warranted: standard published algorithms that fully cover the capability (cite them by name); recorded data we already hold that pins the behaviour (call counts, draw logs, payload statistics, parameter schema); the open-source ancestor still matching the live class/method names; capabilities that need only parity of OUTPUT, not of method.' },
]

const minePrompt = (r) => `${GROUND}

LANE improvements/${r.id}. You are the weakness miner for ${r.name}. Goal: the raw material for designing something BETTER than the reference.
Read completely: ${r.files.map(F).join(', ')} (especially their "failure modes", "creator's stated design philosophy/constraints", "useful facts from comment threads" and "open questions" sections). Then go back to the ORIGINAL comment threads (the "## Comments" section of the post.md files those findings cite, plus research/devlogs/**/post.md comments) and harvest what USERS ask for, complain about, or work around. Add what our recordings show (captures: retries/discards in console traces such as "Unable to build a street!/canal", "discard", reroll workarounds, time per stage vs size, render cost vs generation cost, limits of zoom/resolution/export).
Produce a weakness ledger: each entry = {weakness, who says so (creator / users ×count / recorded), evidence citation, user impact, root cause as far as knowable, how a new design could beat it, how the win would be MEASURED, risk of over-correcting (what the reference gets right here)}. Group by: generation robustness, geometric quality/realism, variety & control, editing & regeneration locality, scale & performance, rendering & style, labels & typography, data model/export/interop, simulation & content (FTG), UX & workflow. Finish with the 15 highest-value improvement opportunities for this reference.
Write docs/improvements/${r.id}.md.`

phase('Assess')
const perRef = await parallel(REFS.map((r) => () => (async () => {
  const [assessment, mined] = await Promise.all([
    fable(assessPrompt(r), `assess:${r.id}`, 'Assess', CONF_SCHEMA).then(async (a) => {
      const ch = await parallel(LENSES.map((l) => () => fable(challengePrompt(r, l, a), `challenge:${r.id}:${l.key}`, 'Challenge', ADJ_SCHEMA)))
      return { a, ch: ch.filter(Boolean) }
    }),
    opus(minePrompt(r), `mine:${r.id}`, 'Mine', FILE_SCHEMA),
  ])
  return { ref: r.id, ...assessment, mined }
})()))
const refs = perRef.filter(Boolean)
log(`assessed ${refs.length}/4 references; challenges: ${refs.map((x) => `${x.ref}:${x.ch.length}`).join(' ')}`)

phase('Report')
const [confidence, improvements] = await parallel([
  () => fable(`${GROUND}

LANE CONFIDENCE. Write docs/CONFIDENCE.md — the owner-facing answer to "how confident are you of reproducing their code and deriving it". Inputs: docs/confidence/{mfcg,vg,ng,ftg}.md and the eight challenge files docs/confidence/*-challenge-{over,under}.md (read all completely). Rule on every challenged row: accept / partially accept / reject the adjustment, with the reason; where the two lenses conflict, go to the cited evidence yourself. Output: (1) a one-page verdict with FOUR numbers per reference (functional, visual, algorithm-identity, seed-exact) as ranges, not points, plus effort; (2) what drives each number; (3) per-reference capability tables after rulings; (4) "cannot be known from outside" list; (5) the experiments that would move the numbers most (we own a profiler: profiler/README.md; FTG allows one new settlement per IP per day); (6) an explicit statement of what evidence classes were and were not used (no proprietary bundle reading).`, 'report:CONFIDENCE', 'Report', FILE_SCHEMA),
  () => fable(`${GROUND}

LANE IMPROVEMENTS. Write docs/IMPROVEMENTS.md from docs/improvements/{mfcg,vg,ng,ftg}.md (read all completely; spot-check at least 12 cited complaints/admissions at source). Merge duplicates across references into cross-cutting opportunities; rank by (user value × evidence strength) / cost; for each give: the weaknesses it answers (with citations), the design idea, the measurable acceptance criterion (a number or a test we could actually run against our captures or a generated corpus), the restraint clause (what must NOT be lost), and dependencies. Include a section "things the references get right that a rewrite usually breaks". Tag every opportunity BASE (MFCG/FTG town/city generator) / STAGE-2 (neighbourhood composition) / VILLAGE-LATER and rank the BASE ones first. End with the must-have / should-have / later split for the BASE that the architects will be held to, then the stage-2 list.`, 'report:IMPROVEMENTS', 'Report', FILE_SCHEMA),
])

// ───────────────────────── Design → Judge → Synthesize ─────────────────────────
const SPEC = `Your proposal must be concrete enough to start building from, and must cover ALL of:
 1. Scope & product shape: STAGE 1 (the base, built first) — one general town/city generator that fuses MFCG-class (ward partition, twisted bisection, castle/plaza/temple/walls/gates, coast/river/canals, one-click charm, ink style, warp/edit tools) and FTG-class (staged road growth, districts as first-class objects, lots/buildings, walls after layout, harbours/farms/forests, roster-first simulation, editing tools, embedding) "using the best of both" plus our own improvements. State an explicit FUSION THESIS: for every pipeline stage, which reference's approach the base adopts, which it discards, and why (with the measurable criterion), and where a genuinely new mechanism replaces both; apply the owner's DESIGN TIEBREAKER (realism through explicit constraints and precise real-world geometry) whenever the two genuinely conflict, and say where it was applied. STAGE 2 (designed here, built after the base) — the city composed of individual neighbourhoods: the base's district objects must be generatable as NG-class close-ups (blocks, lots, courtyards, hatched roofs, local street identities) with consistent seams, shared seeds and one style system; specify the district→neighbourhood interface and what the base must already carry for it. VILLAGE (VG-class) — a separate later product: list what the base leaves open for it and confirm nothing precludes it; do not design it. Tech stack with reasons (language, runtime targets, rendering backends, build, no dependence on any existing project).
 2. Domain model & schemas: LAYERS (underground / ground / sky — the sewer and floating-island hooks) with z-order and elevation; terrain, water, road graph, planar subdivision (faces: districts/blocks/PLOTS), plots as parcels (owner/use, frontage, access, yard, 0..n buildings — the PLOT MODEL), buildings (footprint, floors, HEIGHTS (eave/ridge per wing, tower height) for a later shadow pass, roof, entrance, use — modelled so a footprint can later be a COMPOSITION of wings/blocks produced by a per-plot building generator (stage 3), with the plot's own sub-seed, boundary and access edge as inputs), walls/gates/towers, fields/forest/trees, labels, entities (institutions, people, factions) — with ids, provenance, versioning; serialization format(s).
 3. Geometry kernel: numeric policy (robust predicates / snapping / tolerances), polygon booleans, offsetting/insetting, straight skeleton, OBB, Voronoi/Delaunay, Poisson-disc, planar graph/DCEL, splines/smoothing, spatial index, noise — for each: build vs adopt (name candidate libraries and their licences), and how degenerate input is handled.
 4. Generation pipeline: stage graph with typed inputs/outputs; the FUSED base layout (how MFCG's cell/ward partition and FTG's staged road growth combine — e.g. grown arterials with partitioned blocks, or partition seeded from a grown skeleton — chosen with evidence, alternatives rejected in writing) behind one strategy interface that STAGE 2 extends with the NG-class district close-up and that a later village product could extend; block→plot→building subdivision (incl. bent/twisted bisection, perimeter blocks, courtyards, and the PLOT MODEL: per-plot site plans with coverage rules, row-house frontages with party walls, multi-building plots for institutions, yards; PLOT GRANULARITY by wealth/assignment — join plots in prosperous neighbourhoods, split them in poor ones, alleys and back lanes emerging between plots); walls, castles, plazas, harbours, bridges, canals, farms, forests, outskirts.
 5. Failure handling: NO whole-map discard-and-retry as the normal path — constraint checks, local repair, bounded local regeneration, fallbacks, and how each failure class is detected and tested.
 6. Determinism: RNG design (named sub-streams per stage/feature so adding a feature does not reshuffle the map; sub-streams per epoch so growing a settlement does not reshuffle what already exists), seed + parameter permalinks, version axes, reproducibility across platforms (floating point policy).
 7. Editing & regeneration locality — EVERYTHING IS EDITABLE (owner, 2026-09-25): every generated element (terrain, water, roads, districts, plots, buildings, walls, greenery, labels, layers) and every rule table and preset can be changed by a user to fit their preference and by us to change the system; edits are first-class objects that persist, undo, survive regeneration and migrate between versions, with the generator repairing around them locally; a user preference/override layer sits above the defaults. Concretely: lock/pin elements, regenerate an area, warp/move vertices, user-drawn roads/water as constraints, and SEMANTIC assignments (name / function / shape class with drift bounds, on one building, one whole neighbourhood, or N dispersed buildings — see ASSIGNMENT HOOK) — and the full lifecycle of edits and assignments: create, read, persist, regenerate, undo, migrate between generator versions.
 8. Rendering & style system: a renderer-independent display list with level of detail from building outline → wings/roofs → rooms (stage-3 hook) and with layers (underground sewers shown through the ground; sky islands casting shadows on it — toggles); style sheets that can reproduce each reference's look (flat ink MFCG; shaded/hatched VG & NG; textured/lit FTG) and new ones; roofs, shadows, hatching, trees, water bands, furrows, road casing, walls; level-of-detail; SVG / Canvas2D / WebGL backends; print/VTT export resolution.
 9. Labels & map furniture: curved district labels (skeleton/OBB-arc), street names, collision handling, legend, scale bar, compass, grid, title.
10. Simulation & content layer (FTG parity; in scope for the base as a module whose depth you must justify with restraint — FTG's roster-first generation is part of "the best of both"): population from size, buildings from a resource/dependency graph, professions, households/family model, schedules/time simulation, factions/religions, name generation — data-driven and replaceable.
11. Export & interop: JSON schema, SVG, PNG, GeoJSON, VTT formats (walls/doors/lights; per-layer levels for sewers and sky islands), 3-D (OBJ/glTF), embedding API/postMessage, permalinks.
12. Performance budgets per stage at the base's three size classes — TOWN / CITY / METROPOLIS (owner, 2026-09-25: the town/city generator scales town → city → metropolis; the separate village product scales thorp → hamlet → village) — using the recorded reference timings as the bar; incremental/async generation, workers, memory.
13. Testing & verification: property tests for kernel invariants, per-stage invariants, seed goldens with declared-shift protocol, visual regression, and REFERENCE-PARITY METRICS computed against our captures (e.g. block-area and building-count distributions, road-angle/segment statistics vs the FTG payload, draw-style checks vs draw records).
14. Package/module layout with key TypeScript-style interfaces (or the equivalent in your chosen language), dependency rules between modules, extension points.
15. PARITY MATRIX (every capability in docs/confidence/*.md → where it lives in your design, tagged BASE / STAGE-2 / VILLAGE-LATER; MFCG and FTG rows must be covered by the base, NG rows by the stage-2 interface, VG rows only checked as not precluded) and IMPROVEMENT MATRIX (every must-have/should-have in docs/IMPROVEMENTS.md → mechanism + acceptance metric).
16. Build plan: base milestones first with exit criteria (the first milestone must produce a viewable MFCG/FTG-class town), the riskiest spikes first (the fused layout, twisted bisection, robust kernel), then the stage-2 neighbourhood-composition milestone; what is deliberately out of scope (the village).
17. Clean-room/legal posture and third-party licence list.`

const ARCHITECTS = [
  { key: 'kernel', brief: 'GEOMETRY-KERNEL-FIRST. Your thesis: every weakness the creators admit traces to fragile geometry (collapsed/intersecting edges, concave shapes, tolerance bugs). Make one robust planar-subdivision model the single spatial truth that every stage reads and writes, and derive everything else from it.' },
  { key: 'pipeline', brief: 'PIPELINE-AND-DETERMINISM-FIRST. Your thesis: the hard problems are orchestration — composable layout strategies, constraint satisfaction with local repair instead of whole-map retries, stable seeds under feature growth, edit/regenerate locality, versioned artifacts with provenance. Design the stage graph and its contracts first; geometry is a service.' },
  { key: 'product', brief: 'RENDERER-AND-PRODUCT-FIRST. Your thesis: users judge maps by the picture and by what they can do with it. Work backwards from the display list, style system, labels, editing UX, export/VTT/3-D interop and the simulation/content layer; let those requirements dictate the domain model and pipeline.' },
]

phase('Design')
const proposals = (await parallel(ARCHITECTS.map((a) => () => fable(`${GROUND}

LANE design/proposal-${a.key}. You are one of three INDEPENDENT architects (you will not see the others' work). Angle — ${a.brief}
Read completely: docs/CONFIDENCE.md, docs/IMPROVEMENTS.md, docs/confidence/{mfcg,vg,ng,ftg}.md (not the challenge files), research/findings/_critic.md, _critic-os.md, _critic-ftg.md, _critic-vg-ng.md, visual-spec.md, os-geometry.md, and — for the stage-3 building hooks — research/findings/manor.md if it exists (watabou's Fantasy Manor: composition grammar, plot fit, size classes). The other findings files (${ALL_FINDINGS.map(F).join(', ')}) total ≈1.6 MB — more than one context holds: read the section outline (grep -n '^#') of EVERY one of them, then read in full every section whose subject your design touches; you must have read the source section before specifying any mechanism that claims parity with it or improves on it — technique detail is the point. List in an appendix which sections you read in full. Use captures/*/*/report.md for numbers.
${SPEC}
Before committing, write down at least two alternative shapes for each hard-to-reverse decision (spatial truth model, numeric policy, RNG/stream design, stack, display-list design) and one sentence on why you reject each.
Write docs/design/proposal-${a.key}.md (no length limit; diagrams as ASCII/mermaid; interfaces as code blocks).`, `architect:${a.key}`, 'Design', FILE_SCHEMA)))).filter(Boolean)
log(`${proposals.length}/3 proposals landed`)

const JUDGES = [
  { key: 'parity', brief: 'CAPABILITY PARITY AND FUSION FIDELITY. Walk every capability in docs/confidence/{mfcg,ftg}.md and the visual-spec findings and check each proposal really covers it in the BASE (not by assertion — by a mechanism that would work); then judge the fusion thesis: does the proposal take the best of MFCG and FTG at each stage with evidence, or is it one reference plus bolt-ons, and where the two conflict did it apply the owner’s DESIGN TIEBREAKER (realism through constraints and precision) without sacrificing legibility? Then walk docs/confidence/ng.md for stage-2 readiness (does the district→neighbourhood interface really carry what NG needs?) and docs/confidence/vg.md only for preclusion. Count uncovered/hand-waved capabilities per tier.' },
  { key: 'improvement', brief: 'IMPROVEMENT REALISM AND RESTRAINT. Walk docs/IMPROVEMENTS.md. For each must-have/should-have: is the mechanism real, is the acceptance metric measurable, does it sacrifice something the references get right? Punish feature-listing without mechanism and "better" without a number.' },
  { key: 'engineering', brief: 'ENGINEERING SOUNDNESS. Numeric robustness, determinism under feature growth, lifecycle of edits (create/read/persist/regenerate/undo/migrate), performance budgets vs recorded timings, testability, dependency/licence risk, build-plan realism, complexity budget (what can a small team actually ship?).' },
]
phase('Judge')
const verdicts = (await parallel(JUDGES.map((j) => () => fable(`${GROUND}

LANE design/judge-${j.key}. You are a judge on a three-judge panel. Lens — ${j.brief}
Read completely the three proposals docs/design/proposal-{kernel,pipeline,product}.md plus docs/CONFIDENCE.md and docs/IMPROVEMENTS.md (and findings where you need to check a claim). Score each proposal 0–100 on your lens with itemised reasons, list strengths, list fatal or major flaws (be specific: section + why it fails), name the winner on your lens, and list the best ideas from the NON-winning proposals that must be grafted into the final architecture.
Write docs/design/judge-${j.key}.md.`, `judge:${j.key}`, 'Judge', JUDGE_SCHEMA)))).filter(Boolean)

phase('Synthesize')
const arch = await fable(`${GROUND}

LANE ARCHITECTURE. You are the chief architect. Read completely: the three proposals docs/design/proposal-{kernel,pipeline,product}.md, the three judge reports docs/design/judge-{parity,improvement,engineering}.md, docs/CONFIDENCE.md, docs/IMPROVEMENTS.md. Panel summary: ${JSON.stringify(verdicts.map((v) => ({ lens: v.lens, winner: v.winner, scores: v.scores.map((s) => [s.proposal, s.score_0_100]) })))}.
First write docs/design/judging.md (score table, per-lens winners, the graft list, every fatal/major flaw raised and how the final design answers it). Then write docs/ARCHITECTURE.md: ONE coherent architecture built on the strongest proposal with the grafts applied — not a concatenation — structured as PART I the base (the MFCG/FTG-fused town/city generator with our improvements; complete and build-ready), PART II the stage-2 neighbourhood composition (interface, seams, what the base already carries), PART III what a later village product would need from the base (one page, no design). It must satisfy every item of this specification:
${SPEC}
Add: a "Delegated decisions" section — the owner has deferred ALL judgment to this program and will not rule on technical choices, so for each decision that would normally be the owner's (product scope cuts, the technology stack, licence posture, simulation depth) you DECIDE: state the choice as final, the one-paragraph rationale in plain language a non-programmer can follow, the alternative you rejected, and what it would cost to reverse later; and a "Judgment calls" section in the form "chose X over Y because Z". Every plain-language summary in the document must be readable by someone who does not code.`, 'synthesize:ARCHITECTURE', 'Synthesize', FILE_SCHEMA)

// ───────────────────────── Red team → Revise → Verify (loop until dry, max 2 rounds) ─────────────────────────
const AUDIT_SLICES = [
  { key: 'mfcg', kb: 650, files: ['os-model', 'os-wards-render', 'mfcg-posts-a', 'mfcg-posts-b', 'mfcg-devlogs-a', 'mfcg-devlogs-b', 'profile-mfcg', '_critic-os'] },
  { key: 'vg', kb: 430, files: ['vg-posts-a', 'vg-posts-b', 'vg-ng-devlogs', 'profile-village', '_critic-vg-ng'] },
  { key: 'ng-shared', kb: 400, files: ['profile-neighbourhood', 'watabou-extra-a', 'watabou-extra-b', 'os-geometry', 'visual-spec', '_critic'] },
  { key: 'ftg', kb: 450, files: ['ftg-posts-a', 'ftg-posts-b', 'ftg-posts-c', 'ftg-docs-params', 'ftg-payload-visual', '_critic-ftg'] },
]
const RT = [
  { key: 'geometry', brief: 'GEOMETRY ROBUSTNESS. Attack the kernel and every stage that consumes it with the failure classes the creators themselves report (collapsed/intersecting edges on concave shapes, empty areas inside walls, unbounded loops, null OBB on degenerate polygons, duplicate road intersections, z-fighting/overdraw, self-intersecting user strokes) and classic ones (sliver faces, near-collinear offsets, skeleton events at equal times, tolerance drift across stages, float non-determinism across platforms).' },
  { key: 'lifecycle', brief: 'DETERMINISM AND STATE LIFECYCLE. Trace every piece of state through create, read, persist, regenerate/re-derive, grow/extend (the EVOLUTION hook: run the pipeline incrementally on an existing settlement; wall→road conversion), undo/restore, clone, migrate/import. Hunt for the write that survives one path and ghosts another: edits lost on area-regenerate, pins that dangle after roster/geometry change, seeds that reshuffle when a feature is added, goldens that silently shift, version-migration gaps, permalink/param drift.' },
  { key: 'scale', brief: 'PERFORMANCE AND SCALE. Hold the design to the recorded bars (MFCG size-80 ≈ 200 ms generation; FTG city ≈ 3 s server-side with 4.3k nodes/5.3k edges/2.8k buildings and a 50k-population ceiling; render cost dominating in OpenFL) — find super-linear stages, memory blow-ups, main-thread stalls, display-list sizes that break SVG, label placement cost, worker/serialization overhead.' },
  { key: 'visual', brief: 'VISUAL PARITY AND CRAFT. Using research/findings/visual-spec.md and the screenshots under captures/, check the style system can actually reproduce the looks the staged scope requires — for the BASE: ink+flat MFCG with curved labels and FTG textures, lighting, shore foam, field hedgerows, LOD; for STAGE 2: NG hatched roofs with ridges, shadows, courtyards; VG relief/contours/water bands/tree crowns/furrows only as a not-precluded check — AND that the claimed visual improvements would not reduce legibility.' },
  { key: 'mfcg', brief: 'MFCG-CLASS PARITY WITHIN THE FUSED BASE. Ward/district partition and semantics (venue mix, no residential wards), twisted bisection with local retry, castle/citadel repair, plaza/temple/market placement, curtain walls with gates/towers and the no-buildings-against-walls rule, coast/river/canals/bridges, greens/farms/outskirts/shantytowns, warp/rotate/reroll-per-ward editing, size classes and seed permalinks, one-click charm and speed (size-80 ≈ 200 ms), ink style with curved labels and legend. Find what the fusion loses from MFCG, and where FTG-style road growth would break MFCG-class legibility; and whether the PLOT MODEL (footprints + yards instead of lots drawn as buildings) keeps MFCG’s dense, legible fabric at city zoom.' },
  { key: 'ftg', brief: 'FTG-CLASS PARITY WITHIN THE FUSED BASE. Road-growth stages and presets (Medieval, twisty, American, Ringed), districts as first-class objects, lots/building placement modes, walls-after-stage, harbours, farmland modes, islands/coasts, terrain/heightmap + 3-D view, 50k-person simulation with family units, schedules and time, building/resource dependency graph, editing tools (draw roads/rivers, regenerate area, bulk edit), wire format and sync/embedding. Find what the architecture under-scopes or gets structurally wrong.' },
  { key: 'improve', brief: 'IMPROVEMENT CLAIMS AND SCOPE. For every claimed improvement: is it real, measurable, and affordable? Which ones are wishful? Where does the design exceed what a small team can ship, and what should be cut or staged? Also check clean-room/licence posture of every named third-party dependency and that nothing depends on any project outside this folder.' },
]
phase('RedTeam')
const [coverage, ...redteam] = await parallel([
  () => parallel(AUDIT_SLICES.map((sl) => () => opus(`${GROUND}

LANE validation/coverage-audit-${sl.key}. Build the master capability checklist for your slice: every distinct technique/capability recorded in ANY of these findings files — ${sl.files.map(F).join(', ')} — read them all completely (≈${sl.kb} KB) and enumerate (expect one to two hundred rows; deduplicate within the slice but keep per-reference variants; include the critic addenda and the post-critic capture addenda). Then read docs/ARCHITECTURE.md completely and, for each row, tag its tier — BASE (MFCG/FTG capability the base must cover), STAGE-2 (NG capability the district→neighbourhood interface must be ready for) or VILLAGE-LATER (VG capability: only check that the base does not preclude it) — and mark COVERED (cite section) / PARTIAL (what is missing) / MISSING, or for VILLAGE-LATER rows NOT-PRECLUDED / PRECLUDED (with why). Also list architecture features that no row in ANY findings file and no item in docs/IMPROVEMENTS.md motivates (scope creep) — restricted to what you can judge from your slice. Write docs/validation/coverage-audit-${sl.key}.md with the full table and a summary of PARTIAL/MISSING rows by severity.`, `redteam:coverage-${sl.key}`, 'RedTeam', FILE_SCHEMA))),
  ...RT.map((l) => () => fable(`${GROUND}

LANE validation/redteam-${l.key}. You are a red-team reviewer of docs/ARCHITECTURE.md. Lens — ${l.brief}
Read the architecture completely, then the findings/captures your lens needs. Try to BREAK the design: concrete input/state → wrong output, crash, non-determinism, lost edit, missed budget, uncovered capability, unmeasurable claim. No generic advice — every finding needs a concrete failure scenario, the evidence, and the specific change required. Severity: blocker (design cannot meet a stated goal), major (will bite, needs design change), minor.
Write docs/validation/redteam-${l.key}.md.`, `redteam:${l.key}`, 'RedTeam', RT_SCHEMA)),
])
let open = redteam.filter(Boolean).flatMap((r) => r.findings.map((f) => ({ ...f, lens: r.lens })))
log(`red team: ${open.length} findings (${open.filter((f) => f.severity === 'blocker').length} blocker, ${open.filter((f) => f.severity === 'major').length} major)`)

let round = 0
while (round < 2 && open.some((f) => f.severity !== 'minor')) {
  round++
  phase('Revise')
  await fable(`${GROUND}

LANE ARCHITECTURE-VALIDATION (revision round ${round}). Read docs/ARCHITECTURE.md, the four docs/validation/coverage-audit-{mfcg,vg,ng-shared,ftg}.md, every docs/validation/redteam-*.md${round > 1 ? ' and docs/validation/verify-*.md' : ''} completely. For EVERY finding and every PARTIAL/MISSING coverage row decide: FIX (change the architecture — edit docs/ARCHITECTURE.md in place, coherent with the rest, not a bolt-on appendix), REJECT (with a reason that would survive the reviewer), or DEFER (documented, with rationale and what would trigger it). Open findings this round: ${JSON.stringify(open.filter((f) => f.severity !== 'minor').map((f) => ({ id: f.id, lens: f.lens, severity: f.severity, change: f.required_change })))}.
Maintain docs/ARCHITECTURE-VALIDATION.md: a disposition table (finding id, lens, severity, disposition, where fixed in ARCHITECTURE.md, reason) for all rounds, plus a changelog of the architecture by round.`, `revise:round-${round}`, 'Revise', FILE_SCHEMA)
  phase('Verify')
  const checks = (await parallel(['geometry+lifecycle', 'scale+ftg+mfcg', 'visual+improve+coverage'].map((grp) => () => opus(`${GROUND}

LANE validation/verify-${grp}-r${round}. Verification after revision round ${round}, lens group: ${grp}. Read docs/ARCHITECTURE-VALIDATION.md, the matching docs/validation/redteam-*.md (and the four docs/validation/coverage-audit-*.md files if in your group) and the REVISED docs/ARCHITECTURE.md completely. For each blocker/major finding in your group: confirm the claimed fix is really in the architecture text and really defeats the failure scenario — default to UNRESOLVED if the fix is an assertion rather than a mechanism, or if a REJECT/DEFER reason does not hold. Then hunt for NEW problems introduced by the revision. Write docs/validation/verify-${grp}-r${round}.md.`, `verify:${grp}:r${round}`, 'Verify', VERIFY_SCHEMA)))).filter(Boolean)
  open = checks.flatMap((c) => [...c.unresolved.map((u) => ({ id: u.id, severity: u.severity, required_change: u.required_change, lens: c.lens })), ...c.new_findings.map((n) => ({ id: n.id, severity: n.severity, required_change: n.required_change, lens: c.lens }))])
  log(`after round ${round}: ${open.length} open (${open.filter((f) => f.severity !== 'minor').length} blocker/major)`)
  if (!open.some((f) => f.severity !== 'minor')) {
    // Fable as validator (owner, 2026-09-25): the Opus verifiers confirm that fixes landed; before the loop is allowed to
    // exit, one Fable validator reads the revised architecture whole and hunts for what the verifiers' lens groups cannot see.
    const fin = await fable(`${GROUND}

LANE validation/final-validation-r${round}. The Opus verifiers report no blocker/major finding open after revision round ${round}. You are the FINAL VALIDATOR. Read the REVISED docs/ARCHITECTURE.md completely and docs/ARCHITECTURE-VALIDATION.md (all dispositions), then every docs/validation/redteam-*.md and docs/validation/verify-*-r${round}.md. Your job is what the lens-grouped verifiers cannot do: (1) whole-design coherence — do the fixes applied for different lenses contradict each other, duplicate mechanisms, or leave a stage contract inconsistent with another; (2) every REJECT and DEFER disposition — does the reason really hold against the reviewer's failure scenario; (3) regressions of the references' strengths (legibility, speed, charm, one-click simplicity) introduced by the revisions; (4) the staged scope — is the BASE complete and build-ready on its own, is stage-2 readiness real rather than asserted, is the village merely not precluded; (5) any blocker the seven lenses and the coverage audit structurally could not raise (e.g. build-plan order that cannot deliver the first milestone, a licence conflict, an owner decision left implicit). Concrete failure scenario + evidence + required change for each; severity blocker / major / minor; do not repeat findings already dispositioned unless the disposition is wrong. Write docs/validation/final-validation-r${round}.md.`, `final-validation:r${round}`, 'Verify', VERIFY_SCHEMA)
    if (fin) open = [...fin.unresolved.map((u) => ({ id: u.id, severity: u.severity, required_change: u.required_change, lens: 'final-validation' })), ...fin.new_findings.map((n) => ({ id: n.id, severity: n.severity, required_change: n.required_change, lens: 'final-validation' }))]
    log(`final validation after round ${round}: ${open.length} findings (${open.filter((f) => f.severity !== 'minor').length} blocker/major)`)
  }
}

return {
  confidence: refs.map((x) => ({ ref: x.ref, overall: x.a && x.a.overall, challenges: x.ch.map((c) => ({ lens: c.lens, n: c.adjustments.length, verdict: c.verdict })) })),
  reports: { confidence, improvements },
  proposals: proposals.map((p) => ({ key: p.key, headline: p.headline })),
  judges: verdicts.map((v) => ({ lens: v.lens, winner: v.winner, scores: v.scores.map((s) => [s.proposal, s.score_0_100]) })),
  architecture: arch,
  coverage: (coverage || []).filter(Boolean).map((c) => ({ key: c.key, headline: c.headline })),
  redteam_counts: redteam.filter(Boolean).map((r) => ({ lens: r.lens, n: r.findings.length })),
  rounds: round,
  still_open: open,
}
